void auswerten(auftragListe) {
  gesamt = 0
  for auftrag in auftragListe {
    auftragswert = 0
    for wert in auftrag.positionen {
      auftragswert = auftragswert + wert
    }
    if (auftragswert < 40) gebuehrVermerken()
    gesamt = gesamt + auftragswert
  }
  if (gesamt >= 180) grosskundenHinweis()
}

void pruefen(werte) {
  summe = 0
  for wert in werte {
    summe = summe + wert
    if (wert > 90) alarmSpeichern()
  }
  mittel = summe / werte.length
  if (mittel < 20) heizungEinschalten()
}

void importieren(kennungen) {
  for kennung in kennungen {
    if (kennung == "") {
      leerwertProtokollieren()
    } else {
      laenge = kennung.length
      if (laenge >= 8) {
        uebernehmen()
      } else {
        zurueckweisen()
      }
    }
  }
  importBeenden()
}
